// Split inventory by OS family and build the host lists each Ansible
// control server needs. Never let a CentOS host reach the Ubuntu
// playbook or vice versa.
const rows = items.map(i => i.json);

const centosOS = ['CentOS 6.10', 'CentOS 7.9', 'CentOS 8', 'Rocky 8', 'Rocky 9', 'AlmaLinux 8', 'AlmaLinux 9'];
const ubuntuOS  = ['Ubuntu 22.04', 'Ubuntu 24.04'];

const centos = [];
const ubuntu = [];
const unsupported = [];

for (const s of rows) {
  const label = `${s.os} ${s.os_version}`.trim();
  if (centosOS.some(o => label.includes(o.replace('CentOS ', '').replace('Rocky ', '').replace('AlmaLinux ', '')) && s.os.match(/CentOS|Rocky|Alma/i))) {
    centos.push(s);
  } else if (s.os.match(/Ubuntu/i) && ubuntuOS.some(o => label.includes(o.split(' ')[1]))) {
    ubuntu.push(s);
  } else {
    unsupported.push({ ...s, status: 'UNSUPPORTED_OS' });
  }
}

return [
  { json: { group: 'centos', ansible_server: '172.16.3.64', hosts: centos } },
  { json: { group: 'ubuntu', ansible_server: '172.16.16.108', hosts: ubuntu } },
  { json: { group: 'unsupported', hosts: unsupported } }
];

const STATUS = {
  COMPLIANT: 'COMPLIANT',
  PATCH_AVAILABLE: 'PATCH_AVAILABLE',
  SECURITY_PATCH_AVAILABLE: 'SECURITY_PATCH_AVAILABLE',
  CRITICAL_PATCH_AVAILABLE: 'CRITICAL_PATCH_AVAILABLE',
  UNREACHABLE: 'UNREACHABLE',
  REPOSITORY_ERROR: 'REPOSITORY_ERROR',
  INVENTORY_MISMATCH: 'INVENTORY_MISMATCH',
  UNSUPPORTED_OS: 'UNSUPPORTED_OS'
};

const normalized = [];

for (const item of items) {

  const data = item.json || {};

  const stdout = String(data.stdout || '');
  const stderr = String(data.stderr || '');

  // --------------------------------------------------
  // 1. Detect Ansible command failure
  // --------------------------------------------------

  if (
    stderr.includes('no such option') ||
    stderr.includes('ERROR!') ||
    stderr.includes('fatal:')
  ) {
    normalized.push({
      hostname: 'unknown',
      status: STATUS.UNREACHABLE,
      error: stderr.trim().slice(0, 1000)
    });

    continue;
  }

  // --------------------------------------------------
  // 2. Look for JSON report between markers
  // --------------------------------------------------

  const startMarker = '===PATCH_REPORT_START===';
  const endMarker = '===PATCH_REPORT_END===';

  const start = stdout.indexOf(startMarker);
  const end = stdout.indexOf(endMarker);

  if (start !== -1 && end !== -1 && end > start) {

    const jsonText = stdout
      .substring(start + startMarker.length, end)
      .trim();

    try {

      const report = JSON.parse(jsonText);

      const results =
        report.hosts ||
        report.results ||
        (Array.isArray(report) ? report : [report]);

      for (const r of results) {

        if (!r || !r.hostname) {
          continue;
        }

        let status = STATUS.COMPLIANT;

        if ((Number(r.critical_updates) || 0) > 0) {
          status = STATUS.CRITICAL_PATCH_AVAILABLE;
        }
        else if ((Number(r.security_updates) || 0) > 0) {
          status = STATUS.SECURITY_PATCH_AVAILABLE;
        }
        else if ((Number(r.available_updates) || 0) > 0) {
          status = STATUS.PATCH_AVAILABLE;
        }

        if (r.unreachable) {
          status = STATUS.UNREACHABLE;
        }
        else if (r.repo_error) {
          status = STATUS.REPOSITORY_ERROR;
        }
        else if (
          r.detected_os &&
          r.inventory_os &&
          r.detected_os !== r.inventory_os
        ) {
          status = STATUS.INVENTORY_MISMATCH;
        }

        normalized.push({
          hostname: r.hostname,
          ip_address: r.ip_address || r.ansible_host || '',
          os: r.os || '',
          os_version: r.os_version || '',
          kernel: r.kernel || '',
          environment: r.environment || '',
          criticality: r.criticality || '',
          patch_group: r.patch_group || '',

          available_updates:
            Number(r.available_updates) || 0,

          security_updates:
            Number(r.security_updates) || 0,

          critical_updates:
            Number(r.critical_updates) || 0,

          reboot_required:
            Boolean(r.reboot_required),

          status
        });
      }

      continue;

    } catch (e) {

      normalized.push({
        hostname: 'unknown',
        status: STATUS.REPOSITORY_ERROR,
        error: 'Unable to parse Ansible JSON report',
        parse_error: e.message,
        raw: jsonText.slice(0, 1000)
      });

      continue;
    }
  }

  // --------------------------------------------------
  // 3. If no JSON report was found
  // --------------------------------------------------

  const hostMatch = stdout.match(
    /ok:\s*\[([^\]]+)\]/
  );

  normalized.push({
    hostname: hostMatch ? hostMatch[1] : 'unknown',
    status: STATUS.REPOSITORY_ERROR,
    error: 'Ansible completed but JSON report was not found in stdout',
    stdout: stdout.slice(-1500),
    stderr: stderr.slice(-1000)
  });
}

return normalized.map(r => ({
  json: r
}));

// Roll normalized rows up into the monthly compliance summary.
const rows = items.map(i => i.json);
const total = rows.length;

const count = s => rows.filter(r => r.status === s).length;
const compliant = count('COMPLIANT');

const summary = {
  patch_cycle: new Date().toLocaleString('en-US', { month: 'long', year: 'numeric' }),
  total_servers: total,
  compliant_servers: compliant,
  patch_available: count('PATCH_AVAILABLE'),
  security_updates_available: count('SECURITY_PATCH_AVAILABLE'),
  critical_updates_available: count('CRITICAL_PATCH_AVAILABLE'),
  reboot_required: rows.filter(r => r.reboot_required).length,
  unreachable_servers: count('UNREACHABLE'),
  repository_errors: count('REPOSITORY_ERROR'),
  inventory_mismatches: count('INVENTORY_MISMATCH'),
  unsupported_os: count('UNSUPPORTED_OS'),
  patch_compliance_percentage: total ? Math.round((compliant / total) * 1000) / 10 : 0,
  servers: rows
};

return [{ json: summary }];
